 <section id="pause" class="screen hidden"><div class="modal"><div class="eyebrow">SIMULATION PAUSED</div><h2>Catch your breath.</h2><p>The cores aren't going anywhere. Probably.</p><div class="modal-actions"><button class="primary" id="resumeBtn">RESUME <span>↗</span></button><button class="secondary" id="quitBtn">EXIT RUN</button></div></div></section>
 <section id="end" class="screen hidden"><div class="modal"><div class="eyebrow" id="endEyebrow">SIMULATION COMPLETE</div><h2 id="endTitle">ARENA CLEAN.</h2><p id="endCopy">Stylish work, operator.</p><div class="result-stat"><span>CORES PURGED</span><b id="endKills">0</b></div><div class="result-stat"><span>FINAL SCORE</span><b id="endScore">000000</b></div><div class="result-stat"><span>PERSONA</span><b id="endPersona">VEX</b></div><div class="modal-actions" style="margin-top:17px"><button class="primary" id="againBtn">RUN IT BACK <span>↗</span></button><button class="secondary" id="menuBtn">LOADOUT</button></div></div></section>
 </main>
 <script>
+const canvas=document.querySelector('#view'),ctx=canvas.getContext('2d');
+const agents=[
+ {name:'VEX',role:'THE CHAOS PILOT',quote:'“I have a plan. It is mostly improvising.”',agility:92,attitude:97,colors:['#d8ff3e','#ff4d83','#5be7ff','#b68cff'],skins:['ACID POP','HOT MESS','GLITCH','NIGHT SHIFT'],lines:['Cute little core. Let’s unplug it.','I meant to do that. Probably.','One more round? Obviously.']},
+ {name:'MIRA',role:'THE COOL HEAD',quote:'“Breathe in. Aim small. Make it count.”',agility:76,attitude:84,colors:['#5be7ff','#ff9b43','#f2e7d0','#fa76b9'],skins:['ICE BREAKER','SUNSET','PORCELAIN','BUBBLEGUM'],lines:['Focus. One clean shot.','They’re getting predictable.','We’re still in control.']},
+ {name:'BYTE',role:'THE WALKING PATCH NOTE',quote:'“Statistically? I’m your best option.”',agility:84,attitude:73,colors:['#b68cff','#d8ff3e','#ff4d83','#6ee7a4'],skins:['PURPLE HAZE','ACID POP','PINK NOISE','MINT CONDITION'],lines:['Threat assessment: mildly annoying.','Updating my win percentage.','I will log that as intentional.']}
+];
+let agentIndex=0,skinIndex=0;
+function agentSvg(color){return `<svg viewBox="0 0 220 270" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="coat" x2="0" y2="1"><stop stop-color="${color}"/><stop offset="1" stop-color="#15202d"/></linearGradient><linearGradient id="face" x2="0" y2="1"><stop stop-color="#e4b7a0"/><stop offset="1" stop-color="#9b655c"/></linearGradient></defs><ellipse cx="111" cy="251" rx="71" ry="10" fill="#0008"/><path d="M56 263l8-70 18-51h56l23 49 9 72h-43l-8-50h-17l-7 50z" fill="url(#coat)" stroke="#9aa8b6" stroke-opacity=".35"/><path d="M81 148l30 25 27-25 16 24-23 27h-43l-22-27z" fill="#182532"/><path d="M84 95c0-34 51-47 63-4l-3 40c-8 22-50 26-61-4z" fill="url(#face)"/><path d="M80 105c-2-45 11-63 39-66 26-3 43 20 34 54l-14-18-36 8-11 24z" fill="#20232c"/><path d="M88 93c14-6 33-10 55-7" fill="none" stroke="${color}" stroke-width="8"/><path d="M98 116h8m20 0h8" stroke="#282a30" stroke-width="3" stroke-linecap="round"/><path d="M104 136q10 6 21 0" fill="none" stroke="#723e40" stroke-width="2"/><path d="M78 192l-32 31 16 12 33-26m55-19 35 32-13 13-38-22" fill="#273646" stroke="#9aa8b6" stroke-opacity=".4"/><path d="M91 174l21 25 22-25" fill="none" stroke="${color}" stroke-width="4"/><circle cx="111" cy="184" r="5" fill="${color}"/><path d="M91 226h21m5 0h19" stroke="#d7dee5" stroke-opacity=".2" stroke-width="3"/></svg>`}
+function renderLoadout(){let a=agents[agentIndex],color=a.colors[skinIndex];document.querySelector('#agentVisual').innerHTML=agentSvg(color);document.querySelector('#agentName').textContent=a.name;document.querySelector('#agentRole').textContent=a.role;document.querySelector('#agentQuote').textContent=a.quote;document.querySelector('#agentCount').textContent=`0${agentIndex+1} / 03`;document.querySelector('#skinName').textContent=a.skins[skinIndex];document.querySelector('#agilityNum').textContent=a.agility;document.querySelector('#attitudeNum').textContent=a.attitude;document.querySelector('#agilityBar').style.width=a.agility+'%';document.querySelector('#attitudeBar').style.width=a.attitude+'%';document.querySelector('#skinDots').innerHTML=a.colors.map((c,i)=>`<button class="skin-dot ${i===skinIndex?'active':''}" style="background:${c}" aria-label="${a.skins[i]}" data-skin="${i}"></button>`).join('');document.querySelector('#agentSwitch').innerHTML=agents.map((x,i)=>`<button class="agent-select ${i===agentIndex?'active':''}" data-agent="${i}">${x.name} // ${x.role.split(' ').slice(-1)}</button>`).join('');document.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{skinIndex=+b.dataset.skin;renderLoadout()});document.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>{agentIndex=+b.dataset.agent;skinIndex=0;renderLoadout()})}
+renderLoadout();
+const $=s=>document.querySelector(s),menu=$('#menu'),hud=$('#hud'),pauseScreen=$('#pause'),endScreen=$('#end');
+function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),1350)}
+function resize(){let dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
+let game={active:false,paused:false,over:false,won:false,player:null,enemies:[],bullets:[],map:[],keys:{},score:0,kills:0,wave:1,ammo:12,totalAmmo:60,reload:0,shootCd:0,damageCd:0,elapsed:0,shake:0,damageFlash:0,fireHeld:false,mouseDown:false,mouseLastX:0,toastTimer:0,moveTouch:{x:0,y:0},lookTouch:null};
+const FOV=Math.PI/3, MAP=['111111111111111','100000000000001','101110010111101','100010010000001','101010111010101','100000000010001','101110101110101','100000100000001','101010111010101','100010000010001','101110110110101','100000000000001','111111111111111'];
+function resetGame(){game.player={x:7.5,y:1.55,angle:Math.PI/2,hp:100};game.map=MAP.map(r=>r.split('').map(Number));game.enemies=[];game.bullets=[];game.score=0;game.kills=0;game.wave=1;game.ammo=12;game.totalAmmo=60;game.reload=0;game.shootCd=0;game.damageCd=0;game.elapsed=0;game.over=false;game.won=false;spawnWave();syncHud()}
+function spawnWave(){let count=4+(game.wave-1)*2;for(let i=0;i<count;i++){let p;for(let n=0;n<100;n++){let x=1+Math.random()*13,y=1+Math.random()*11;if(game.map[Math.floor(y)]?.[Math.floor(x)]===0&&Math.hypot(x-game.player.x,y-game.player.y)>4&&!game.enemies.some(e=>Math.hypot(x-e.x,y-e.y)<1)){p={x,y};break}}if(!p)p={x:13.3,y:11.2};game.enemies.push({x:p.x,y:p.y,hp:2+Math.floor((game.wave-1)/2),maxHp:2+Math.floor((game.wave-1)/2),speed:.45+Math.random()*.15,attack:Math.random(),hit:0,phase:Math.random()*6.3,dead:false})}showToast(`ROUND ${String(game.wave).padStart(2,'0')} // CORES DETECTED`)}
+function startGame(){menu.classList.add('hidden');pauseScreen.classList.add('hidden');endScreen.classList.add('hidden');hud.classList.remove('hidden');resetGame();game.active=true;game.paused=false;if(innerWidth>760&&canvas.requestPointerLock)canvas.requestPointerLock();lastTime=performance.now();requestAnimationFrame(loop)}
+$('#playBtn').onclick=startGame;$('#againBtn').onclick=startGame;$('#menuBtn').onclick=()=>{endScreen.classList.add('hidden');hud.classList.add('hidden');menu.classList.remove('hidden');game.active=false};$('#resumeBtn').onclick=()=>{game.paused=false;pauseScreen.classList.add('hidden');if(innerWidth>760)canvas.requestPointerLock();lastTime=performance.now();requestAnimationFrame(loop)};$('#quitBtn').onclick=()=>{game.active=false;game.paused=false;document.exitPointerLock?.();pauseScreen.classList.add('hidden');hud.classList.add('hidden');menu.classList.remove('hidden')};$('#controlBtn').onclick=()=>alert('WASD to move • Mouse to aim • Click to fire • R to reload • Shift to sprint • Esc to pause. Mobile: left stick to move, drag right side to aim, FIRE button to shoot.');

