$('#quitBtn').onclick=()=>{game.active=false;game.paused=false;document.exitPointerLock?.();pauseScreen.classList.add('hidden');hud.classList.add('hidden');menu.classList.remove('hidden')};$('#controlBtn').onclick=()=>alert('WASD to move • Mouse to aim • Click to fire • R to reload • Shift to sprint • Esc to pause. Mobile: left stick to move, drag right side to aim, FIRE button to shoot.');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function isWall(x,y){return game.map[Math.floor(y)]?.[Math.floor(x)]!==0}
function canStand(x,y,r=.19){return !isWall(x-r,y-r)&&!isWall(x+r,y-r)&&!isWall(x-r,y+r)&&!isWall(x+r,y+r)}
function castRay(angle){let px=game.player.x,py=game.player.y,dx=Math.cos(angle),dy=Math.sin(angle),dist=0;while(dist<20){dist+=.035;let x=px+dx*dist,y=py+dy*dist;if(isWall(x,y)){let side=(Math.floor(x)!==Math.floor(x-dx*.04))?0:1;return{dist,side,x,y,wallX:side?x-Math.floor(x):y-Math.floor(y)}}}return{dist:20,side:0,x:px+dx*dist,y:py+dy*dist,wallX:0}}
function drawWorld(){let w=innerWidth,h=innerHeight,p=game.player;let sky=ctx.createLinearGradient(0,0,0,h*.53);sky.addColorStop(0,'#111a29');sky.addColorStop(1,'#27354a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h*.53);let floor=ctx.createLinearGradient(0,h*.5,0,h);floor.addColorStop(0,'#202936');floor.addColorStop(.38,'#131b25');floor.addColorStop(1,'#090d14');ctx.fillStyle=floor;ctx.fillRect(0,h*.5,w,h*.5);let cols=Math.ceil(w/3),depth=new Float32Array(cols);for(let i=0;i<cols;i++){let x=i*3,angle=p.angle+((x/w)-.5)*FOV,r=castRay(angle),correct=r.dist*Math.cos(angle-p.angle);depth[i]=correct;let wallH=Math.min(h*2,h/(correct*.72)),top=h/2-wallH/2;let shade=clamp(1-correct/12,.23,1)*(r.side?.78:1);let checker=(Math.floor(r.x*2)+Math.floor(r.y*2))%2;let base=checker?'#586b83':'#43566d';ctx.fillStyle=base;ctx.globalAlpha=shade;ctx.fillRect(x,top,4,wallH);ctx.globalAlpha=1;ctx.fillStyle='rgba(200,225,255,.055)';ctx.fillRect(x,top,4,2);if(r.wallX<.025||r.wallX>.975){ctx.fillStyle='#9fb7d333';ctx.fillRect(x,top,2,wallH)}if(wallH<h*.8&&correct<6){ctx.fillStyle=`rgba(90,231,255,${.06*(1-correct/6)})`;ctx.fillRect(x,top+wallH*.45,3,Math.max(1,wallH*.06))}}
// glowing arena floor markings
ctx.save();ctx.globalAlpha=.12;for(let i=1;i<12;i++){let y=h/2+(h/2)*(i/12)*(i/12);ctx.strokeStyle='#5be7ff';ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.restore();
let sprites=game.enemies.filter(e=>!e.dead).map(e=>({e,d:Math.hypot(e.x-p.x,e.y-p.y)})).sort((a,b)=>b.d-a.d);for(let item of sprites){let e=item.e,dx=e.x-p.x,dy=e.y-p.y,d=item.d,rel=Math.atan2(dy,dx)-p.angle;while(rel>Math.PI)rel-=Math.PI*2;while(rel<-Math.PI)rel+=Math.PI*2;if(Math.abs(rel)>FOV*.72||d<.2)continue;let sx=(.5+rel/FOV)*w,screenH=Math.min(h*1.3,h/(d*.85)),sy=h/2-screenH*.48+Math.sin(game.elapsed*3+e.phase)*screenH*.018;let ci=Math.floor((sx/w)*cols);if(depth[clamp(ci,0,cols-1)]<d-.25)continue;drawEnemy(sx,sy,screenH,e,d)}drawWeapon(w,h)}
function drawEnemy(x,y,size,e,d){let bodyW=size*.42,head=size*.24,ground=y+size*.95;let flash=e.hit>0;ctx.save();ctx.globalAlpha=clamp(1-d/17,.35,1);ctx.translate(x,ground);ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(0,0,bodyW*.63,size*.055,0,0,Math.PI*2);ctx.fill();let col=flash?'#fff':(agents[(agentIndex+1)%3].colors[skinIndex%4]);ctx.fillStyle='#111b28';ctx.beginPath();ctx.moveTo(-bodyW*.45,-size*.53);ctx.lineTo(-bodyW*.34,-size*.84);ctx.lineTo(bodyW*.34,-size*.84);ctx.lineTo(bodyW*.47,-size*.5);ctx.lineTo(bodyW*.32,-size*.08);ctx.lineTo(-bodyW*.3,-size*.08);ctx.closePath();ctx.fill();ctx.fillStyle=col;ctx.fillRect(-bodyW*.42,-size*.84,bodyW*.84,size*.055);ctx.fillStyle='#253344';ctx.fillRect(-bodyW*.45,-size*.48,bodyW*.2,size*.42);ctx.fillRect(bodyW*.25,-size*.48,bodyW*.2,size*.42);ctx.fillStyle='#c8917d';ctx.beginPath();ctx.ellipse(0,-size*.89,head*.48,head*.52,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#101720';ctx.beginPath();ctx.arc(0,-size*.95,head*.52,Math.PI,0);ctx.fill();ctx.fillStyle=col;ctx.fillRect(-head*.48,-size*.9,head*.96,size*.055);ctx.fillStyle='#ff4d83';ctx.fillRect(-head*.24,-size*.89,head*.17,size*.025);ctx.fillRect(head*.08,-size*.89,head*.17,size*.025);if(e.hp<e.maxHp){ctx.fillStyle='#111';ctx.fillRect(-bodyW*.45,-size*1.04,bodyW*.9,4);ctx.fillStyle='#ff4d83';ctx.fillRect(-bodyW*.45,-size*1.04,bodyW*.9*e.hp/e.maxHp,4)}ctx.restore()}
function drawWeapon(w,h){let bob=Math.sin(game.elapsed*8)*(Math.abs(game.moveTouch.x)+Math.abs(game.moveTouch.y)>.1?7:2),cx=w*.5,base=h+20+bob,kick=game.shootCd>.12?16:0;ctx.save();ctx.translate(cx,base+kick);ctx.fillStyle='#182331';ctx.beginPath();ctx.moveTo(-w*.1,0);ctx.lineTo(-w*.075,-h*.19);ctx.lineTo(-w*.035,-h*.28);ctx.lineTo(w*.055,-h*.28);ctx.lineTo(w*.11,0);ctx.closePath();ctx.fill();ctx.fillStyle=agents[agentIndex].colors[skinIndex];ctx.fillRect(-w*.055,-h*.24,w*.11,h*.025);ctx.fillStyle='#080d14';ctx.fillRect(-w*.029,-h*.32,w*.058,h*.11);ctx.fillRect(-w*.04,-h*.2,w*.08,h*.08);ctx.fillStyle='#758599';ctx.fillRect(-w*.016,-h*.29,w*.032,h*.08);if(game.shootCd>.19){ctx.fillStyle='#ffe07a';ctx.beginPath();ctx.moveTo(0,-h*.32);ctx.lineTo(-13,-h*.38);ctx.lineTo(0,-h*.44);ctx.lineTo(10,-h*.37);ctx.fill()}ctx.restore()}
function drawRadar(){let el=$('#radar');el.querySelectorAll('.radar-dot').forEach(n=>n.remove());let p=game.player;if(!p)return;for(let e of game.enemies){if(e.dead)continue;let dx=e.x-p.x,dy=e.y-p.y,ca=Math.cos(-p.angle),sa=Math.sin(-p.angle),rx=dx*ca-dy*sa,ry=dx*sa+dy*ca,scale=40/7,xx=50+rx*scale,yy=50+ry*scale;if(xx>4&&xx<96&&yy>4&&yy<96){let d=document.createElement('i');d.className='radar-dot';d.style.left=xx+'%';d.style.top=yy+'%';el.appendChild(d)}}}
function syncHud(){if(!game.player)return;$('#hpText').textContent=`${Math.max(0,Math.ceil(game.player.hp))} / 100`;$('#hpFill').style.width=clamp(game.player.hp,0,100)+'%';$('#hpFill').classList.toggle('low',game.player.hp<32);$('#ammoNow').textContent=game.ammo;$('#ammoTotal').textContent=game.totalAmmo;$('#scoreNum').textContent=String(game.score).padStart(6,'0');$('#waveNum').textContent=String(game.wave).padStart(2,'0');$('#hudAgent').textContent=agents[agentIndex].name;$('#hintText').textContent=`${game.enemies.filter(e=>!e.dead).length} ROGUE CORES REMAINING`;drawRadar()}

