function syncHud(){if(!game.player)return;$('#hpText').textContent=`${Math.max(0,Math.ceil(game.player.hp))} / 100`;$('#hpFill').style.width=clamp(game.player.hp,0,100)+'%';$('#hpFill').classList.toggle('low',game.player.hp<32);$('#ammoNow').textContent=game.ammo;$('#ammoTotal').textContent=game.totalAmmo;$('#scoreNum').textContent=String(game.score).padStart(6,'0');$('#waveNum').textContent=String(game.wave).padStart(2,'0');$('#hudAgent').textContent=agents[agentIndex].name;$('#hintText').textContent=`${game.enemies.filter(e=>!e.dead).length} ROGUE CORES REMAINING`;drawRadar()}
