function fire(){if(!game.active||game.paused||game.over||game.shootCd>0||game.reload>0)return;if(game.ammo<=0){reload();return}game.ammo--;game.shootCd=.24;let p=game.player,best=null,bestDist=99;for(let e of game.enemies){if(e.dead)continue;let dx=e.x-p.x,dy=e.y-p.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx)-p.angle;while(a>Math.PI)a-=Math.PI*2;while(a<-Math.PI)a+=Math.PI*2;if(Math.abs(a)<.09+Math.atan(.25/d)&&d<bestDist){let ray=castRay(Math.atan2(dy,dx));if(ray.dist>=d-.3){best=e;bestDist=d}}}if(best){best.hp--;best.hit=.12;game.score+=best.hp<=0?150:35;$('#crosshair .hitmarker').classList.add('active');setTimeout(()=>$('#crosshair .hitmarker').classList.remove('active'),100);if(best.hp<=0){best.dead=true;game.kills++;game.score+=100;addFeed(`${agents[(agentIndex+1)%3].name} CORE PURGED`);if(game.kills%3===0){game.totalAmmo=Math.min(72,game.totalAmmo+6);showToast('SUPPLY CACHE // +6 AMMO')} }}syncHud()}
function addFeed(text){let f=$('#feed');f.innerHTML=`<div>+ ${text}</div>`+f.innerHTML;while(f.children.length>4)f.lastElementChild.remove()}
function enemyAttack(e,dt){if(e.attack>0)return;let p=game.player,d=Math.hypot(p.x-e.x,p.y-e.y);if(d>8){e.attack=.7;return}let ang=Math.atan2(p.y-e.y,p.x-e.x),r=castRay(ang);if(r.dist<d-.25){e.attack=.7;return}game.bullets.push({x:e.x,y:e.y,dx:Math.cos(ang)*2.5,dy:Math.sin(ang)*2.5,life:2});e.attack=1.8+Math.random()*.8}
function update(dt){let p=game.player;game.elapsed+=dt;game.shootCd=Math.max(0,game.shootCd-dt);game.damageCd=Math.max(0,game.damageCd-dt);game.damageFlash=Math.max(0,game.damageFlash-dt);game.shake=Math.max(0,game.shake-dt*20);if(game.reload>0){game.reload-=dt;if(game.reload<=0){let take=Math.min(12-game.ammo,game.totalAmmo);game.ammo+=take;game.totalAmmo-=take;syncHud()}}let forward=(game.keys.KeyW||game.keys.ArrowUp?1:0)-(game.keys.KeyS||game.keys.ArrowDown?1:0)-game.moveTouch.y,strafe=(game.keys.KeyD||game.keys.ArrowRight?1:0)-(game.keys.KeyA||game.keys.ArrowLeft?1:0)+game.moveTouch.x;let mag=Math.hypot(forward,strafe);if(mag>1){forward/=mag;strafe/=mag}let speed=(game.keys.ShiftLeft||game.keys.ShiftRight||game.sprinting?3.8:2.6)*dt,dx=(Math.cos(p.angle)*forward-Math.sin(p.angle)*strafe)*speed,dy=(Math.sin(p.angle)*forward+Math.cos(p.angle)*strafe)*speed;if(canStand(p.x+dx,p.y))p.x+=dx;if(canStand(p.x,p.y+dy))p.y+=dy;
for(let e of game.enemies){if(e.dead)continue;e.attack-=dt;e.hit=Math.max(0,e.hit-dt);let vx=p.x-e.x,vy=p.y-e.y,d=Math.hypot(vx,vy);if(d>1.45){let step=e.speed*dt,nx=e.x+vx/d*step,ny=e.y+vy/d*step;if(canStand(nx,e.y,.16))e.x=nx;if(canStand(e.x,ny,.16))e.y=ny}else enemyAttack(e,dt)}
for(let b of game.bullets){b.life-=dt;b.x+=b.dx*dt;b.y+=b.dy*dt;if(isWall(b.x,b.y)){b.life=0;continue}if(Math.hypot(b.x-p.x,b.y-p.y)<.25&&game.damageCd<=0){p.hp-=10;game.damageCd=.45;game.damageFlash=.24;game.shake=5;$('#damageflash').style.opacity='.8';setTimeout(()=>$('#damageflash').style.opacity='0',150);syncHud();if(p.hp<=0){finish(false);return}}}game.bullets=game.bullets.filter(b=>b.life>0);if(game.enemies.every(e=>e.dead)){if(!game.waveDelay)game.waveDelay=2.2;game.waveDelay-=dt;if(game.waveDelay<=0){game.waveDelay=0;if(game.wave>=3){finish(true);return}game.wave++;game.player.hp=Math.min(100,game.player.hp+14);game.ammo=12;game.totalAmmo=Math.min(72,game.totalAmmo+12);spawnWave();syncHud()}}else game.waveDelay=0;if(game.fireHeld)fire();syncHud()}
function finish(won){game.over=true;game.active=false;game.won=won;document.exitPointerLock?.();hud.classList.add('hidden');endScreen.classList.remove('hidden');$('#endEyebrow').textContent=won?'SIMULATION COMPLETE':'SIGNAL LOST';$('#endTitle').textContent=won?'ARENA CLEAN.':'CORE DOWN.';$('#endCopy').textContent=won?agents[agentIndex].lines[1]:'The cores got you this time. The arena remembers.';$('#endKills').textContent=game.kills;$('#endScore').textContent=String(game.score).padStart(6,'0');$('#endPersona').textContent=`${agents[agentIndex].name} // ${agents[agentIndex].skins[skinIndex]}`}
let lastTime=0;function loop(now){if(!game.active||game.paused)return;let dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;update(dt);ctx.save();if(game.shake)ctx.translate((Math.random()-.5)*game.shake,(Math.random()-.5)*game.shake);drawWorld();ctx.restore();requestAnimationFrame(loop)}
addEventListener('keydown',e=>{game.keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reload();if(e.code==='Escape'&&game.active&&!game.paused){game.paused=true;pauseScreen.classList.remove('hidden');document.exitPointerLock?.()}});addEventListener('keyup',e=>game.keys[e.code]=false);addEventListener('blur',()=>{game.keys={};game.fireHeld=false});
