stick.addEventListener('pointerup',()=>{stickPointer=null;game.moveTouch={x:0,y:0}});stick.addEventListener('pointercancel',()=>{stickPointer=null;game.moveTouch={x:0,y:0}});
let lookId=null,lastLookX=0;hud.addEventListener('pointerdown',e=>{if(innerWidth>760||e.target.closest('.mobile-controls'))return;if(e.clientX<innerWidth*.35)return;lookId=e.pointerId;lastLookX=e.clientX;hud.setPointerCapture(e.pointerId)});hud.addEventListener('pointermove',e=>{if(lookId===e.pointerId&&game.active&&!game.paused){game.player.angle+=(e.clientX-lastLookX)*.009;lastLookX=e.clientX}});hud.addEventListener('pointerup',e=>{if(e.pointerId===lookId)lookId=null});$('#fireTouch').addEventListener('pointerdown',e=>{e.preventDefault();game.fireHeld=true;fire()});$('#fireTouch').addEventListener('pointerup',()=>game.fireHeld=false);$('#fireTouch').addEventListener('pointercancel',()=>game.fireHeld=false);$('#reloadTouch').onclick=reload;$('#sprintTouch').addEventListener('pointerdown',()=>game.sprinting=true);$('#sprintTouch').addEventListener('pointerup',()=>game.sprinting=false);$('#sprintTouch').addEventListener('pointercancel',()=>game.sprinting=false);
